import { readFileSync } from "node:fs";

const DEFAULTS = Object.freeze({ exportsDir: "exports", keepDays: 30 });

/** config.json merged over the defaults; a missing or unreadable file is the defaults, and the reason is on stderr once. */
export function loadConfig(path = "config.json") {
  try {
    return { ...DEFAULTS, ...JSON.parse(readFileSync(path, "utf8")) };
  } catch (err) {
    process.stderr.write(`config: ${path} not read (${err.code ?? err.message}); using defaults\n`);
    return { ...DEFAULTS };
  }
}

